def kapitalwert(inv, rf, zins, jahre):
    return -inv + sum(
        rf / (1 + zins) ** t
        for t in range(1, jahre + 1))

for f in (1.0, 0.75, 0.5):
    rf = 16000 * f - 4000
    kw = kapitalwert(25000, rf, 0.05, 5)
    print(f"{f:.0%}: {kw:.0f} €")

